export const open: Excerpt = { file: "src/video.rs", start: 54, code: "pub fn open(device: &wgpu::Device, filename: &str) -> Result<Self, String> {\n    let hal = unsafe { device.as_hal::<wgpu::hal::api::Dx12>() }\n        .ok_or(\"wgpu must use the D3D12 backend\")?;\n    let file = CString::new(filename).map_err(|e| e.to_string())?;\n    let native = NonNull::new(unsafe { nv_open(file.as_ptr(), hal.raw_device().as_raw()) })\n        .ok_or(\"Media Foundation / Video Codec SDK initialization failed (see stderr)\")?;\n    // Decode initial + lookahead frame before importing the D3D12 resources into wgpu.\n    // On failure, always release the native decoder and CUDA resources.\n    let result = (|| {\n        let width = unsafe { nv_width(native.as_ptr()) } as u32;\n        let height = unsafe { nv_height(native.as_ptr()) } as u32;\n        if width == 0 || height == 0 { return Err(\"Invalid video dimensions\".to_owned()); }\n        let current = Self::decode(native)?;\n        let pending = Self::decode(native)?;\n        let mut textures = Vec::with_capacity(SLOTS);\n        for slot in 0..SLOTS {\n            let resource_ptr = unsafe { nv_texture(native.as_ptr(), slot as i32) };\n            if resource_ptr.is_null() { return Err(format!(\"D3D12 resource slot {slot} missing\")); }\n            // C++ AddRef's, Rust from_raw takes ownership of the additional COM reference.\n            let resource = unsafe { ID3D12Resource::from_raw(resource_ptr) };\n            let desc = wgpu::TextureDescriptor {\n                label: Some(\"Video Codec SDK CUDA-shared RGBA texture\"),\n                size: wgpu::Extent3d { width, height, depth_or_array_layers: 1 },\n                mip_level_count: 1,\n                sample_count: 1,\n                dimension: wgpu::TextureDimension::D2,\n                format: wgpu::TextureFormat::Rgba8Unorm,\n                usage: wgpu::TextureUsages::TEXTURE_BINDING,\n                view_formats: &[],\n            };\n            let wrapped = unsafe {\n                wgpu::hal::dx12::Device::texture_from_raw(\n                    resource,\n                    desc.format,\n                    desc.dimension,\n                    desc.size,\n                    desc.mip_level_count,\n                    desc.sample_count,\n                )\n            };\n            let tex = unsafe { device.create_texture_from_hal::<wgpu::hal::api::Dx12>(\n                wrapped, &desc, wgpu::TextureUses::RESOURCE) };\n            textures.push(tex);\n        }\n        let start = Instant::now();\n        let fallback_interval = Duration::from_millis(33);\n        let due = if pending.pts_100ns > current.pts_100ns {\n            duration_100ns(pending.pts_100ns)\n        } else { fallback_interval };\n        Ok(Self { native, textures, current, pending, start,\n            next_due: start + due, fallback_interval })\n    })();\n    if result.is_err() { unsafe { nv_close(native.as_ptr()) }; }\n    result\n}" };

export const update: Excerpt = { file: "src/video.rs", start: 112, code: "pub fn update(&mut self, device: &wgpu::Device) -> Result<bool, String> {\n    let now = Instant::now();\n    if now < self.next_due { return Ok(false); }\n    // Safe first milestone. Serializes CUDA writes against *all* queued wgpu reads.\n    // A future revision can replace this with CUDA-imported D3D12 fences per slot.\n    device.poll(wgpu::PollType::Wait { submission_index: None, timeout: None })\n        .map_err(|e| e.to_string())?;\n    let previous_pts = self.current.pts_100ns;\n    self.current = self.pending;\n    if self.current.pts_100ns <= previous_pts {\n        // Video loop: the native reader rewound to the beginning.\n        self.start = now;\n    }\n    let new_pending = Self::decode(self.native)?;\n    let delta = new_pending.pts_100ns - self.current.pts_100ns;\n    if delta > 0 {\n        self.fallback_interval = duration_100ns(delta).min(Duration::from_secs(1));\n        self.next_due = self.start + duration_100ns(new_pending.pts_100ns);\n    } else {\n        // Next packet may be from the next video loop, or contain a duplicate timestamp.\n        self.next_due = now + self.fallback_interval;\n    }\n    self.pending = new_pending;\n    Ok(true)\n}" };

export const background: Excerpt = { file: "src/main.rs", start: 42, code: "/// The window background, rgb(69, 80, 93), as clear values for `format`. Clear colors are\n/// linear on sRGB targets, so the display value is decoded there.\nfn background(format: wgpu::TextureFormat) -> wgpu::Color {\n    let [r, g, b] = [69.0, 80.0, 93.0].map(|v: f64| {\n        let c = v / 255.0;\n        if !format.is_srgb() { c } else if c <= 0.04045 { c / 12.92 } else { ((c + 0.055) / 1.055).powf(2.4) }\n    });\n    wgpu::Color { r, g, b, a: 1.0 }\n}" };

export const swapchain: Excerpt = { file: "src/main.rs", start: 110, code: "// The CUDA kernel writes display-encoded (gamma) RGB into Rgba8Unorm textures, so\n// sampled values are already what the screen should show. A non-sRGB target passes\n// them through; an sRGB one would gamma-encode them a second time (washed out).\nlet format = caps.formats.iter().copied().find(|f| !f.is_srgb()).unwrap_or(caps.formats[0]);\nprintln!(\"Swapchain format: {format:?}\");\nlet clear = background(format);" };

export const bindGroups: Excerpt = { file: "src/main.rs", start: 166, code: "let bind_groups: Vec<wgpu::BindGroup> = video.textures.iter().enumerate().map(|(_slot, tex)| {\n    let texture_view = tex.create_view(&Default::default());\n    device.create_bind_group(&wgpu::BindGroupDescriptor {\n        label: Some(\"NVDEC frame + MVP bindings\"), layout: &layout,\n        entries: &[\n            wgpu::BindGroupEntry { binding: 0, resource: uniform.as_entire_binding() },\n            wgpu::BindGroupEntry { binding: 1, resource: wgpu::BindingResource::TextureView(&texture_view) },\n            wgpu::BindGroupEntry { binding: 2, resource: wgpu::BindingResource::Sampler(&sampler) },\n        ],\n    })\n}).collect();" };

export const setBindGroup: Excerpt = { file: "src/main.rs", start: 276, code: "pass.set_pipeline(&self.pipeline);\npass.set_bind_group(0, &self.bind_groups[self.video.current_slot()], &[]);\npass.set_vertex_buffer(0, self.vertices.slice(..));\npass.set_index_buffer(self.indices.slice(..), wgpu::IndexFormat::Uint16);\npass.draw_indexed(0..36, 0, 0..1);" };

export const shader: Excerpt = { file: "src/cube.wgsl", start: 1, code: "struct Uniforms { mvp: mat4x4<f32> }\n@group(0) @binding(0) var<uniform> uniforms: Uniforms;\n@group(0) @binding(1) var video: texture_2d<f32>;\n@group(0) @binding(2) var video_sampler: sampler;\n\nstruct VertexInput {\n    @location(0) pos: vec3<f32>,\n    @location(1) uv: vec2<f32>,\n};\nstruct VertexOutput {\n    @builtin(position) clip: vec4<f32>,\n    @location(0) uv: vec2<f32>,\n};\n\n@vertex\nfn vs_main(v: VertexInput) -> VertexOutput {\n    var result: VertexOutput;\n    result.clip = uniforms.mvp * vec4<f32>(v.pos, 1.0);\n    result.uv = v.uv;\n    return result;\n}\n\n@fragment\nfn fs_main(v: VertexOutput) -> @location(0) vec4<f32> {\n    return textureSample(video, video_sampler, v.uv);\n}" };
